"""Interaction functions for the 'Diagnoses and Problems List' and 'Diagnosis and Staging' UI windows in the Mosaiq application.
These windows are displayed when selecting the 'Diagnosis' button from the the D and I window, and the 'Add Diagnosis' button
from the 'Diagnoses and Problems List' window, respectively."""

from .objects.mosaiq_d_and_i_objects import DandI
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
from interops.libraries.squish_actions import CommonActions


def __find_diagnosis_and_staging_window(waitTimeout: int = 30000) -> bool:
    """Searches for the Diagnosis and Staging window of the D and I UI. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :param int waitTimeout: The timeout in milliseconds to wait for the Diagnosis and Staging window to appear
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DandI.diagnosis_and_staging_Window, waitTimeout) is not None else False

def __find_diagnoses_and_problems_window(waitTimeout: int = 30000) -> bool:
    """Searches for the Diagnoses and Problems window of the D and I UI. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :param int waitTimeout: The timeout in milliseconds to wait for the Diagnoses and Problems window to appear
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DandI.diagnoses_and_problems_Window, timeout=waitTimeout) is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_diagnosis_and_staging_window(waitTimeout: int = 30000) -> bool:
    """Locates D and I - Diagnoses and Problems window > clicks the Add Diagnosis button > then waits for the Diagnosis and Staging
    UI window to appear.

    # NOTE: Although the Diagnosis and Staging window may appear after clicking the Add Diagnosis button, it can take at
    least 30 seconds (or more) for Squish to recognise it as an active (ready state) window. This waitTimeout should be
    extended for slow performing Mosaiq machines.

    :param int waitTimeout: The timeout in milliseconds to wait for the Diagnosis and Staging window to appear
    :return: True if the Diagnosis and Staging window is opened, False otherwise
    """
    if __find_diagnoses_and_problems_window():
        CommonActions.left_click_object(DandI.diagnoses_and_problems_Add_Diagnosis_Button)
        return __find_diagnosis_and_staging_window(waitTimeout)
    return False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def type_in_diagnoses_field_and_confirm(diagnosesDescription: str) -> None:
    """Locates the D and I - Diagnosis and Staging window > types a given diagnoses description > confirms the found results in the popup UI.

    :param str diagnosesDescription:
    """
    if __find_diagnosis_and_staging_window():
        # Alternate implementation to edit the diagnosis text field (slow but reliable)
        #diagnosis_field_status = CommonActions.find_object(DandI.diagnosis_and_staging_Diagnosis_Field, 90000)
        #CommonActions.type_in_textfield(DandI.diagnosis_and_staging_Diagnosis_Field, diagnosesDescription)

        CommonActions.left_click_object(DandI.diagnosis_and_staging_Diagnosis_Parent_Field)
        CommonActions.native_text_type(diagnosesDescription)
        CommonActions.left_click_object(DandI.diagnosis_and_staging_Diagnosis_PageTab_All)
        results = DandI.diagnosis_and_staging_Diagnosis_PageTab_Results
        results['value'] = diagnosesDescription
        CommonActions.double_click_object(results)
        CommonActions.press_enter_key()

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_save_and_affirm_diagnosis() -> None:
    """Locates the D and I - Diagnosis and Staging window > then clicks the Save & Affirm button in the UI.
    """
    if __find_diagnosis_and_staging_window():
        CommonActions.left_click_object(DandI.diagnosis_and_staging_Diagnosis_Save_Affirm_Button)
        CommonActions.wait_for_object_to_disappear(DandI.diagnosis_and_staging_Window, 10)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_entered_diagnosis() -> None:
    """Locates the D and I - Diagnoses and Problems window > double clicks the first diagnosis row in the table > then waits for the
    Diagnosis and Staging window to appear.
    """
    if __find_diagnoses_and_problems_window():
        CommonActions.double_click_object(DandI.diagnoses_and_problems_First_Diagnosis_Row, 3)
        CommonActions.find_object(DandI.diagnosis_and_staging_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_diagnoses_and_problems_change_btn() -> None:
    """Locates the D and I - Diagnoses and Problems window > clicks the Change button.
    """
    if __find_diagnoses_and_problems_window():
        CommonActions.left_click_object(DandI.diagnoses_and_problems_Change_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_diagnoses_and_problems_close_btn() -> None:
    """Locates the D and I - Diagnoses and Problems window > clicks the Close button.
    """
    if __find_diagnoses_and_problems_window():
        CommonActions.left_click_object(DandI.diagnoses_and_problems_Close_Button)
        CommonActions.wait_for_object_to_disappear(DandI.diagnoses_and_problems_Window, 10)